    "name_ro": "Sfântul Ierarh Sofronie, Patriarhul Ierusalimului",
    "name_ru": "Святитель Софроний, патриарх Иерусалимский",
    "title": "Composer of Great Blessing of Waters & Defender of the Holy City",
    "title_it": "Autore delle Preghiere Teofaniche e Patriarca di Gerusalemme",
