    "title_ru": "Составитель чина Великого освящения воды, защитник святынь",
    "color": "white",
    "rank": "feast",
    "quote": "«Trinity above all essence, goodness transcending all goodness, look down upon us who glorify Thy holy name!»",
    "quote_it": "«Trinità sovrasostanziale, bontà ineffabile, volgi il Tuo sguardo su quanti glorificano il Tuo Santo Nome!»",
    "quote_ro": "«Treime mai presus de fire, Bunătate mai presus de orice bunătate, caută spre noi cei ce slăvim Numele Tău cel Sfânt!»",
    "quote_ru": "«Троице Пресущественная, Преблагая, призри на нас, прославляющих святое имя Твое!»",
    "bio": "Wrote the Life of St. Mary of Egypt and the majestic hymns of Theophany; negotiated protection for Christian holy sites in Jerusalem.",
    "bio_it": "Scrisse la Vita di santa Maria Egiziaca e i grandiosi inni del Battesimo del Signore.",
