    "name_ro": "Sfântul Cuvios Teofan Mărturisitorul și Sfântul Grigorie Dialogul, Episcopul Romei",
    "name_ru": "Преподобный Феофан Исповедник и святитель Григорий Двоеслов, папа Римский",
