    "title_ru": "Летописец византийский и составитель Литургии Преждеосвященных Даров",
    "color": "white",
    "rank": "feast",
    "quote": "«Now the powers of heaven do minister invisibly with us: behold, the King of Glory enters!»",
    "quote_it": "«Ora le potenze dei cieli servono invisibilmente con noi: ecco, il Re della Gloria fa il Suo ingresso!»",
    "quote_ro": "«Acum Puterile cerești împreună cu noi nevăzut slujesc: iată Împăratul Slavei intră!»",
