    "title_it": "Ritorno del Patriarca Confessore",
    "title_ro": "Întoarcerea moaștelor Patriarhului mărturisitor al sfintelor icoane",
    "title_ru": "Торжественное перенесение мощей исповедника веры",
    "color": "white",
    "rank": "memorial",
    "quote": "«The memory of the just is blessed: but the name of the wicked shall rot.»",
    "quote_it": "«La memoria del giusto è benedetta; il nome degli empi svanisce nel nulla.»",
    "quote_ro": "«Pomenirea dreptului este cu laude, iar numele celor necredincioși se va stinge.»",
    "quote_ru": "«Память праведного пребудет благословенна, а имя нечестивых омерзеет.»",
    "bio": "Exiled 13 years on Proconnesus Island for resisting Leo the Armenian's iconoclasm; brought back incorrupt in 846.",
    "bio_it": "Martire dell'esilio per le sacre icone, il suo corpo incorrotto fu accolto solennemente a Costantinopoli.",
