    "name_ro": "Sfântul Cuvios Benedict de Nursia și Sfântul Mucenic Alexandru din Pidna",
    "name_ru": "Преподобный Венедикт Нурсийский и мученик Александр Пиднский",
    "title": "Father of Western Monasticism & Teacher of 'Ora et Labora'",
    "title_it": "Padre del Monachesimo d'Occidente e Maestro di 'Ora et Labora'",
    "title_ro": "Luminătorul monahismului apusean dinainte de schismă",
    "title_ru": "Отец западного монашества древней неразделенной Церкви",
    "color": "white",
    "rank": "feast",
    "quote": "«Prefer nothing whatsoever to the love of Christ! Pray and work in the holy presence of God.»",
    "quote_it": "«Nulla anteporre all'amore di Cristo! Prega e lavora alla santa presenza di Dio.»",
    "quote_ro": "«Nimic să nu puneți înaintea dragostei lui Hristos! Rugați-vă și lucrați în prezența lui Dumnezeu!»",
