    "title_it": "Vescovo Intrepido di Siria",
    "title_ro": "Păstorul sirian uns cu miere și expus la soare pentru Hristos",
    "title_ru": "Епископ Сирийский, обмазанный медом и преданный на растерзание осам",
    "color": "white",
    "rank": "memorial",
    "quote": "«I look down on you from my height, while you crawl in the dust below, blind to the true God!»",
