    "quote_ru": "«Я смотрю на вас с высоты небесной, а вы пресмыкаетесь во прахе земном!»",
    "bio": "Elder bishop hung in a basket smeared with honey under the desert sun to be stung by wasps; his serene endurance won even pagan admirers.",
    "bio_it": "Spalmato di miele e sospeso al sole nel cesto, sopportò con beffardo sorriso le punture delle vespe.",
    "bio_ro": "Bătrânul episcop atârnat în coș uns cu miere a biruit cruzimea păgânilor prin răbdare îngerească.",
