    "name_it": "San Giovanni Climaco, Autore della Scala del Paradiso",
    "name_ro": "Sfântul Cuvios Ioan Scărarul (autorul Scării Raiului)",
    "name_ru": "Преподобный Иоанн Лествичник, игумен Синайский",
