    "name_de": "Hl. Johannes Klimakos, Verfasser der Himmelsleiter",
    "name_pt": "São João Clímaco, Autor da Escada do Paraíso",
    "title": "Sinai Abbot & Architect of the Thirty Steps to Divine Union",
