    "quote_ro": "«Pocăința este reînnoirea botezului. Dragostea este asemănarea cu Dumnezeu, pe cât este cu putință omului.»",
    "quote_ru": "«Покаяние есть возобновление крещения. Любовь есть уподобление Богу, сколько сие доступно смертным.»",
    "bio": "Abbot of Saint Catherine's Monastery on Mount Sinai whose spiritual classic 'The Ladder' has nourished Christian monastics for 1,400 years.",
    "bio_it": "Autore della sublime 'Scala Paradisi' che descrive i trenta gradini delle virtù fino alla perfetta carità.",
    "bio_ro": "Pustnic pe Muntele Sinai vreme de 40 de ani, a scris 'Scara dumnezeiescului urcuș' citită în tot Postul Mare.",
    "bio_ru": "Игумен Синайской обители, написавший знаменитую 'Лествицу' добродетелей, возводящую от земли на небо.",
