    "title_ru": "Участник I Вселенского Собора, чудотворец Гангрский",
    "color": "white",
    "rank": "memorial",
    "quote": "«Lord, lay not this sin to their charge! Forgive them, for they know not what they do.»",
    "quote_it": "«Signore, non imputare loro questo peccato: perdonali, non sanno quello che fanno!»",
