    "title": "Christ's Faithful Martyr Cast into the Red-Hot Bronze Bull",
    "title_it": "Il Martire Fedele Ricordato nell'Apocalisse",
    "title_ro": "Martorul cel credincios al lui Hristos pomenit în Apocalipsă și Tămăduitorul durerilor de dinți",
    "title_ru": "Верный свидетель Христов, помянутый в Апокалипсисе, целитель зубной боли",
    "color": "blue",
    "rank": "feast",
    "quote": "«Antipas was my faithful martyr, who was slain among you, where Satan dwelleth.»",
    "quote_it": "«Antipa, il mio fedele testimone, fu messo a morte tra voi, dove abita Satana.»",
    "quote_ro": "«Antipa, martorul Meu cel credincios, a fost ucis la voi, unde locuiește satana!»",
    "quote_ru": "«Антипа, свидетель Мой верный, умерщвлен у вас, где живет сатана.»",
