    "bio_it": "Gettato nel toro di bronzo arroventato a Pergamo; invocato universalmente contro i dolori dentari e di gola.",
    "bio_ro": "Pus de viu într-un bou de aramă încins în foc; este grabnic tămăduitor al durerilor cumplite de măsele.",
    "bio_ru": "Брошен в раскаленного медного быка в Пергаме; по молитвам святого верующие получают облегчение от зубной боли.",
    "scriptureRef": "Revelation 2:13",
