    "quote_ru": "«Ввержен был в реку Бузэу, предав душу свою непорочную в руце Спасителя.»",
    "bio": "Sabbas, a devout cantor in Dacia (Romania), was drowned in Buzău River by pagan Goths in 372 for refusing idol meat; his passion was sent to St. Basil the Great.",
    "bio_it": "Saba fu annegato nel fiume Buzău in Romania; gli Atti del suo martirio furono inviati a san Basilio Magno.",
    "bio_ro": "Cântăreț bisericesc în ținutul Buzăului, înecat de goții păgâni în 372; moaștele sale au fost trimise Sfântului Vasile cel Mare în Capadocia.",
    "bio_ru": "Святой Савва пострадал на территории Румынии в 372 году; описание его подвига было направлено Василию Великому.",
