    "color": "white",
    "rank": "memorial",
    "quote": "«Aristarchus my fellowprisoner saluteth you... Trophimus have I left at Miletum sick.»",
    "quote_it": "«Vi saluta Aristarco, mio compagno di carcere... e Trofimo che ho lasciato malato a Mileto.»",
    "quote_ro": "«Vă îmbrățișează Aristarh, cel închis împreună cu mine... iar pe Trofim l-am lăsat bolnav în Milet.»",
