    "color": "white",
    "rank": "memorial",
    "quote": "«Today we enter into the heavenly Jerusalem with our Savior who died on the Cross on this very day!»",
    "quote_it": "«Oggi entriamo nella Gerusalemme celeste con il nostro Salvatore crocifisso per noi!»",
    "quote_ro": "«Astăzi intrăm în Ierusalimul ceresc împreună cu Mântuitorul nostru Cel răstignit pe Cruce!»",
    "quote_ru": "«Днесь входим в Небесный Иерусалим со Спасителем нашим, на Кресте за нас пострадавшим!»",
