    "name_fr": "Saint Justin le Philosophe et ses compagnons martyrs",
    "name_de": "Hl. Justin der Philosoph und Märtyrer",
    "name_pt": "São Justino Filósofo e Mártires de Roma",
    "title": "Apologist and Philosopher of Truth",
    "title_it": "Apologeta e Filosofo della Verità",
