    "name_pt": "Santa Aquilina de Biblos e São Trifílio de Chipre",
    "title": "Twelve-Year-Old Martyr & Eloquent Bishop Disciple of St. Spyridon",
    "title_it": "Giovane fanciulla martire e Discepolo di San Spiridione",
    "title_ro": "Fecioara muceniță din Fenicia și ucenicul Sfântului Spiridon",
    "title_ru": "Отроковица мученица Финикийская и ученик святителя Спиридона",
    "color": "white",
    "rank": "memorial",
    "quote": "«My youth shall not hinder me from confessing the almighty Christ who strengthens me.»",
    "quote_it": "«La mia giovane età non mi impedirà di confessare il Cristo onnipotente che mi dà forza.»",
    "quote_ro": "«Vârsta mea fragedă nu mă va împiedica să mărturisesc pe Hristos cel ce mă întărește!»",
    "quote_ru": "«Юность моя не помешает мне исповедать Христа, укрепляющего немощных.»",
    "bio": "Aquilina at age twelve refused pagan idols and was martyred in Phoenicia (293); Triphyllius was bishop of Nicosia and spiritual son of Spyridon.",
    "bio_it": "A soli dodici anni Aquilina sopportò trafitture con ferri roventi senza rinnegare Cristo.",
