    "color": "white",
    "rank": "memorial",
    "quote": "«We serve an immortal King; earthly emperors cannot shake our allegiance to Jesus Christ.»",
    "quote_it": "«Serviamo un Re immortale; gli imperatori terreni non possono piegare la nostra fedeltà a Cristo.»",
