export function getOrthodoxSaintsForDate(date, userNationality = 'universal', lang = 'it') {
  if (!date) date = new Date();
  const m = date.getMonth() + 1;
  const d = date.getDate();
  const key = `${m}-${d}`;
  const raw = ORTHODOX_SAINTS_CALENDAR[key];
  const rawList = raw ? (Array.isArray(raw) ? raw : [raw]) : [];
  const normNat = (userNationality || 'universal').toLowerCase();

  // Case 1: Universal Calendar — show the international pan-Orthodox mix across nations
  if (!normNat || normNat === 'universal') {
    const universalList = rawList.map(s => {
      let nat = (s.nationality || 'universal').toLowerCase();
      if (rawList.length === 1 && PAN_ORTHODOX_UNIVERSAL_DATES.has(key)) {
        const inferred = inferSaintNationality(s, key);
        nat = inferred === 'universal' ? 'universal' : nat;
      }
      return {
        ...s,
        nationality: nat,
        dateStr: `${m}/${d}`,
        nationalityMeta: getNationalityMeta(nat, lang)
      };
    });

    // Also include curated national Orthodox feasts on this date if not already present
    for (const [natCode, byDate] of Object.entries(NATIONAL_SAINTS_BY_DATE)) {
      const natSaints = (byDate[key] || []).filter(
        ns => ns.traditions.includes('orthodox') || ns.traditions.includes('all')
      );
      for (const ns of natSaints) {
        const exists = universalList.some(
          u => u.name === ns.name || (ns.name_ro && u.name_ro === ns.name_ro)
        );
        if (!exists) {
          universalList.push({
            ...ns,
            dateStr: `${m}/${d}`,
            nationalityMeta: getNationalityMeta(ns.nationality || natCode, lang)
          });
        }
      }
    }

    return universalList;
  }

  // Case 2: Specific Nationality Selected — show ONLY saints of normNat and universal Menaion feasts
  const nationalMatches = (NATIONAL_SAINTS_BY_DATE[normNat]?.[key] || [])
    .filter(ns => ns.traditions.includes('orthodox') || ns.traditions.includes('eastern') || ns.traditions.includes('all'))
    .map(ns => ({
      ...ns,
      nationality: normNat,
      dateStr: `${m}/${d}`,
      nationalityMeta: getNationalityMeta(normNat, lang)
    }));

  // Filter rawList: if multiple entries exist on this day, exclude purely foreign national entries
  let filteredRaw = rawList.filter(s => {
    const rawNat = (s.nationality || 'universal').toLowerCase();
    const inferred = inferSaintNationality(s, key);
    return rawNat === normNat || inferred === normNat || rawNat === 'universal' || PAN_ORTHODOX_UNIVERSAL_DATES.has(key);
  });

  if (filteredRaw.length === 0 && rawList.length > 0) {
    // Pick the general Synaxarion entry and strip any foreign national suffix
    filteredRaw = [rawList[rawList.length - 1]];
  }

  const menaionSaints = filteredRaw.map(s => {
    const cleaned = cleanOrthodoxSaintForNationality(s, normNat);
    const rawNat = (cleaned.nationality || 'universal').toLowerCase();
    const inferred = inferSaintNationality(cleaned, key);
    const finalNat = (rawNat === normNat || inferred === normNat) ? normNat : 'universal';
    return {
      ...cleaned,
      nationality: finalNat,
      dateStr: `${m}/${d}`,
      nationalityMeta: getNationalityMeta(finalNat, lang)
    };
  });

  const combined = [...nationalMatches];
  for (const ms of menaionSaints) {
    const isDup = combined.some(
      c => c.name === ms.name || (c.name_ro && ms.name_ro && c.name_ro === ms.name_ro) || (c.name_it && ms.name_it && c.name_it === ms.name_it)
    );
    if (!isDup) {
      combined.push(ms);
    }
  }

  combined.sort((a, b) => {
    const aMatch = a.nationality === normNat ? 1 : 0;
    const bMatch = b.nationality === normNat ? 1 : 0;
    if (aMatch !== bMatch) return bMatch - aMatch;
    if (a.color === 'red' && b.color !== 'red') return -1;
    if (b.color === 'red' && a.color !== 'red') return 1;
    return 0;
  });

  return combined;
}

